// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE, LogFile} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testFuzz_property(address a, address b) public {
        vm.assume(a != b);
        vm.assume(a != address(0) && b != address(0));
        vm.assume(a.code.length == 0 && b.code.length == 0);
        LogFile la = new LogFile();
        LogFile lb = new LogFile();
        c.SetLogFile(address(la));
        c.Initialized();
        bool ok = true;
        try c.SetLogFile(address(lb)) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
